    public override object parseMarket(object market)
    {
        bool active = (!isEqual(this.safeBool(market, "maintain"), true));
        string? id = this.safeString(market, "pair");
        if (isTrue(isEqual(id, null)))
        {
            throw new ExchangeError ((string)add(this.id, " parseMarket() missing id")) ;
        }
        string uppercaseId = ((string)id).ToUpper();
        string? baseId = this.safeString(market, "base");
        string? quoteId = this.safeString(market, "quote");
        object bs = this.safeCurrencyCode(baseId);
        object quote = this.safeCurrencyCode(quoteId);
        object symbol = add(add(bs, "/"), quote);
        Dictionary<string, object> limits = new Dictionary<string, object>() {
            { "amount", new Dictionary<string, object>() {
                { "min", this.safeNumber(market, "minLimitBaseAmount") },
                { "max", this.safeNumber(market, "maxLimitBaseAmount") },
            } },
            { "price", new Dictionary<string, object>() {
                { "min", null },
                { "max", null },
            } },
            { "cost", new Dictionary<string, object>() {
                { "min", null },
                { "max", null },
            } },
            { "leverage", new Dictionary<string, object>() {
                { "min", null },
                { "max", null },
            } },
        };
        return this.safeMarketStructure(new Dictionary<string, object>() {
            { "id", id },
            { "uppercaseId", uppercaseId },
            { "symbol", symbol },
            { "base", bs },
            { "quote", quote },
            { "baseId", bs },
            { "quoteId", quote },
            { "settle", null },
            { "settleId", null },
            { "type", "spot" },
            { "spot", true },
            { "margin", false },
            { "swap", false },
            { "future", false },
            { "option", false },
            { "contract", false },
            { "linear", null },
            { "inverse", null },
            { "contractSize", null },
            { "expiry", null },
            { "expiryDatetime", null },
            { "strike", null },
            { "optionType", null },
            { "limits", limits },
            { "precision", new Dictionary<string, object>() {
                { "price", this.parseNumber(this.parsePrecision(this.safeString(market, "quotePrecision"))) },
                { "amount", this.parseNumber(this.parsePrecision(this.safeString(market, "basePrecision"))) },
            } },
            { "active", active },
            { "created", null },
            { "info", market },
        });
    }

    public override object parseTicker(object ticker, object market = null)
    {
        //
        //     {
        //         "pair":"btc_twd",
        //         "lastPrice":"1182449.00000000",
        //         "isBuyer":false,
        //         "priceChange24hr":"-1.99",
        //         "volume24hr":"9.13089740",
        //         "high24hr":"1226097.00000000",
        //         "low24hr":"1181000.00000000"
        //     }
        //
        string? marketId = this.safeString(ticker, "pair");
        market = this.safeMarket(marketId, market);
        string? symbol = this.safeString(market, "symbol");
        return this.safeTicker(new Dictionary<string, object>() {
            { "symbol", symbol },
            { "timestamp", null },
            { "datetime", null },
            { "high", this.safeString(ticker, "high24hr") },
            { "low", this.safeString(ticker, "low24hr") },
            { "bid", null },
            { "bidVolume", null },
            { "ask", null },
            { "askVolume", null },
            { "vwap", null },
            { "open", null },
            { "close", this.safeString(ticker, "lastPrice") },
            { "last", this.safeString(ticker, "lastPrice") },
            { "previousClose", null },
            { "change", null },
            { "percentage", this.safeString(ticker, "priceChange24hr") },
            { "average", null },
            { "baseVolume", this.safeString(ticker, "volume24hr") },
            { "quoteVolume", null },
            { "info", ticker },
        }, market);
    }

    /**
     * @method
     * @name bitopro#fetchTicker
     * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market
     * @see https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/public/get_ticker_data.md
     * @param {string} symbol unified symbol of the market to fetch the ticker for
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
     */
    public async override Task<ccxt.Ticker> FetchTicker(string symbol, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if (isTrue(isEqual(this.markets, null)))
        {
            await this.loadMarkets();
        }
        object market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "pair", getValue(market, "id") },
        };
        object response = await this.publicGetTickersPair(this.extend(request, parameters));
        object ticker = this.safeDict(response, "data", new Dictionary<string, object>() {});
        //
        //     {
        //         "data":{
        //             "pair":"btc_twd",
        //             "lastPrice":"1182449.00000000",
        //             "isBuyer":false,
        //             "priceChange24hr":"-1.99",
        //             "volume24hr":"9.13089740",
        //             "high24hr":"1226097.00000000",
        //             "low24hr":"1181000.00000000"
        //         }
        //     }
        //
        return ccxt.BaseExchange.ToTicker(this.parseTicker(ticker, market));
    }

