    /**
     * @method
     * @name bitopro#fetchOrderBook
     * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
     * @see https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/public/get_orderbook_data.md
     * @param {string} symbol unified symbol of the market to fetch the order book for
     * @param {int} [limit] the maximum amount of order book entries to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
     */
    public async override Task<ccxt.OrderBook> FetchOrderBook(string symbol, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if (isTrue(isEqual(this.markets, null)))
        {
            await this.loadMarkets();
        }
        object market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "pair", getValue(market, "id") },
        };
        if (isTrue(!isEqual(limit, null)))
        {
            ((IDictionary<string,object>)request)["limit"] = limit;
        }
        object response = await this.publicGetOrderBookPair(this.extend(request, parameters));
        //
        //     {
        //         "bids":[
        //             {
        //                 "price":"1175271",
        //                 "amount":"0.00022804",
        //                 "count":1,
        //                 "total":"0.00022804"
        //             }
        //         ],
        //         "asks":[
        //             {
        //                 "price":"1176906",
        //                 "amount":"0.0496",
        //                 "count":1,
        //                 "total":"0.0496"
        //             }
        //         ]
        //     }
        //
        return ccxt.BaseExchange.ToOrderBook(this.parseOrderBook(response, getValue(market, "symbol"), null, "bids", "asks", "price", "amount"));
    }

    public override object parseTrade(object trade, object market = null)
    {
        //
        // fetchTrades
        //         {
        //                 "timestamp":1644651458,
        //                 "price":"1180785.00000000",
        //                 "amount":"0.00020000",
        //                 "isBuyer":false
        //         }
        //
        // fetchMyTrades
        //         {
        //                 "tradeId":"5685030251",
        //                 "orderId":"9669168142",
        //                 "price":"11821.8",
        //                 "action":"SELL",
        //                 "baseAmount":"0.01",
        //                 "quoteAmount":"118.218",
        //                 "fee":"0.236436",
        //                 "feeSymbol":"BNB",
        //                 "isTaker":true,
        //                 "timestamp":1644905714862,
        //                 "createdTimestamp":1644905714862
        //         }
        //
        string? id = this.safeString(trade, "tradeId");
        string? orderId = this.safeString(trade, "orderId");
        object timestamp = null;
        if (isTrue(isEqual(id, null)))
        {
            timestamp = this.safeTimestamp(trade, "timestamp");
        } else
        {
            timestamp = this.safeInteger(trade, "timestamp");
        }
        string? marketId = this.safeString(trade, "pair");
        market = this.safeMarket(marketId, market);
        string? symbol = this.safeString(market, "symbol");
        string? price = this.safeString(trade, "price");
        string? type = this.safeStringLower(trade, "type");
        string? side = this.safeStringLower(trade, "action");
        if (isTrue(isEqual(side, null)))
        {
            object isBuyer = this.safeBool(trade, "isBuyer");
            if (isTrue(isEqual(isBuyer, true)))
            {
                side = "buy";
            } else
            {
                side = "sell";
            }
        }
        string? amount = this.safeString(trade, "amount");
        if (isTrue(isEqual(amount, null)))
        {
            amount = this.safeString(trade, "baseAmount");
        }
        object fee = null;
        string? feeAmount = this.safeString(trade, "fee");
        object feeSymbol = this.safeCurrencyCode(this.safeString(trade, "feeSymbol"));
        if (isTrue(!isEqual(feeAmount, null)))
        {
            fee = new Dictionary<string, object>() {
                { "cost", feeAmount },
                { "currency", feeSymbol },
                { "rate", null },
            };
        }
        object isTaker = this.safeBool(trade, "isTaker");
        string? takerOrMaker = null;
        if (isTrue(!isEqual(isTaker, null)))
        {
            if (isTrue(isTaker))
            {
                takerOrMaker = "taker";
            } else
            {
                takerOrMaker = "maker";
            }
        }
        return this.safeTrade(new Dictionary<string, object>() {
            { "id", id },
            { "info", trade },
            { "order", orderId },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", symbol },
            { "takerOrMaker", takerOrMaker },
            { "type", type },
            { "side", side },
            { "price", price },
            { "amount", amount },
            { "cost", null },
            { "fee", fee },
        }, market);
    }

    /**
     * @method
     * @name bitopro#fetchTrades
     * @description get the list of most recent trades for a particular symbol
     * @see https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/public/get_trades_data.md
     * @param {string} symbol unified symbol of the market to fetch trades for
     * @param {int} [since] timestamp in ms of the earliest trade to fetch
     * @param {int} [limit] the maximum amount of trades to fetch
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
     */
    public async override Task<List<ccxt.Trade>> FetchTrades(string symbol, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if (isTrue(isEqual(this.markets, null)))
        {
            await this.loadMarkets();
        }
        object market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "pair", getValue(market, "id") },
        };
        object response = await this.publicGetTradesPair(this.extend(request, parameters));
        object trades = this.safeList(response, "data", new List<object>() {});
        //
        //     {
        //         "data":[
        //             {
        //                 "timestamp":1644651458,
        //                 "price":"1180785.00000000",
        //                 "amount":"0.00020000",
        //                 "isBuyer":false
