    public virtual object parseTransactionStatus(object status)
    {
        Dictionary<string, object> states = new Dictionary<string, object>() {
            { "COMPLETE", "ok" },
            { "INVALID", "failed" },
            { "PROCESSING", "pending" },
            { "WAIT_PROCESS", "pending" },
            { "FAILED", "failed" },
            { "EXPIRED", "failed" },
            { "CANCELLED", "failed" },
            { "EMAIL_VERIFICATION", "pending" },
            { "WAIT_CONFIRMATION", "pending" },
        };
        return this.safeString(states, status, status);
    }

    public override object parseTransaction(object transaction, object currency = null)
    {
        //
        // fetchDeposits
        //
        //    {
        //        "serial": "20220214X766799",
        //        "timestamp": "1644833015053",
        //        "address": "bnb1xml62k5a9dcewgc542fha75fyxdcp0zv8eqfsh",
        //        "amount": "0.20000000",
        //        "fee": "0.00000000",
        //        "total": "0.20000000",
        //        "status": "COMPLETE",
        //        "txid": "A3CC4F6828CC752B9F3737F48B5826B9EC2857040CB5141D0CC955F7E53DB6D9",
        //        "message": "778553959",
        //        "protocol": "MAIN",
        //        "id": "2905906537"
        //    }
        //
        // fetchWithdrawals || fetchWithdraw
        //
        //    {
        //        "serial": "20220215BW14069838",
        //        "timestamp": "1644907716044",
        //        "address": "TKrwMaZaGiAvtXCFT41xHuusNcs4LPWS7w",
        //        "amount": "8.00000000",
        //        "fee": "2.00000000",
        //        "total": "10.00000000",
        //        "status": "COMPLETE",
        //        "txid": "50bf250c71a582f40cf699fb58bab978437ea9bdf7259ff8072e669aab30c32b",
        //        "protocol": "TRX",
        //        "id": "9925310345"
        //    }
        //
        // withdraw
        //
        //    {
        //        "serial": "20220215BW14069838",
        //        "currency": "USDT",
        //        "protocol": "TRX",
        //        "address": "TKrwMaZaGiAvtXCFT41xHuusNcs4LPWS7w",
        //        "amount": "8",
        //        "fee": "2",
        //        "total": "10"
        //    }
        //
        string? currencyId = this.safeString(transaction, "coin");
        object code = this.safeCurrencyCode(currencyId, currency);
        Int64? timestamp = this.safeInteger(transaction, "timestamp");
        string? address = this.safeString(transaction, "address");
        string? tag = this.safeString(transaction, "message");
        string? status = this.safeString(transaction, "status");
        object networkId = this.safeString(transaction, "protocol");
        if (isTrue(isEqual(networkId, "MAIN")))
        {
            networkId = code;
        }
        return new Dictionary<string, object>() {
            { "info", transaction },
            { "id", this.safeString(transaction, "serial") },
            { "txid", this.safeString(transaction, "txid") },
            { "type", null },
            { "currency", code },
            { "network", this.networkIdToCode(networkId, code) },
            { "amount", this.safeNumber(transaction, "total") },
            { "status", this.parseTransactionStatus(status) },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "address", address },
            { "addressFrom", null },
            { "addressTo", address },
            { "tag", tag },
            { "tagFrom", null },
            { "tagTo", tag },
            { "updated", null },
            { "comment", null },
            { "internal", null },
            { "fee", new Dictionary<string, object>() {
                { "currency", code },
                { "cost", this.safeNumber(transaction, "fee") },
                { "rate", null },
            } },
        };
    }

